"""Estimation with benchmarks, rates, products, fractions and quotient checks."""
from algebra_lessons import authored
from number_sense_lessons import source as g
from card_lessons import make_lessons
SPECS=[
authored('estimate-reasonable-mass','Choose a reasonable mass using everyday benchmarks',
 'Which is a reasonable mass for an adult house cat?\n4 grams, 4 kilograms, or 400 kilograms?', '4 kilograms',
 'Which is a reasonable mass for an adult house cat: four grams, four kilograms, or four hundred kilograms?',[
 ('CHECK THE UNIT','Grams measure much smaller masses than kilograms','1 kilogram = 1,000 grams',
 'First check the units. A kilogram is one thousand grams, so confusing these units makes a huge difference.'),
 ('REJECT TOO SMALL','Four grams is only a few small paper clips','4 grams: far too light for an adult cat',
 'Four grams is only the mass of a few small paper clips. An adult cat is much heavier.'),
 ('REJECT TOO LARGE','Four hundred kilograms is far beyond a house cat','400 kilograms: far too heavy',
 'Four hundred kilograms is far heavier than a house cat. That is hundreds of one-kilogram bags.'),
 ('CHOOSE A PLAUSIBLE SCALE','An estimate is a reasonable size, not an exact measurement','4 kilograms = 4,000 grams',
 'Four kilograms is a reasonable choice. Cats vary in mass, so this is not an exact value for every cat. Use familiar objects to judge whether a choice is much too small or large.')],
 g(3,13,1,8),equalities=[('4*1000','4000')]),
authored('estimate-rate-total-stock','Estimate production over several days and add starting stock',
 'A shop starts with 286 cards and makes 47 cards per hour,\n6 hours a day for 3 days. Round 47 to the nearest ten.\nEstimate the new cards and the final stock.', '900 new cards; 1,186 cards in total',
 'A shop starts with two hundred eighty-six cards and makes forty-seven cards per hour, six hours a day for three days. Round forty-seven to the nearest ten. Estimate the new cards and final stock.',[
 ('ROUND THE RATE','Round only the quantity named in the instruction','47 → 50 cards per hour',
 'Forty-seven rounds to fifty cards per hour. Keep the working time and starting stock unchanged.'),
 ('TOTAL HOURS','Multiply hours per day by days','6 × 3 = 18 hours',
 'Six hours each day for three days gives eighteen working hours.'),
 ('NEW PRODUCTION','Multiply the estimated hourly rate by total hours','50 × 18 = 900 new cards',
 'At an estimated fifty cards per hour, eighteen hours produces about nine hundred new cards.'),
 ('FINAL STOCK','Add the original stock once','286 + 900 = 1,186 cards',
 'Add the starting two hundred eighty-six cards once. The estimated final stock is one thousand one hundred eighty-six cards.')],
 g(4,3,'4HW',5),equalities=[('6*3','18'),('50*18','900'),('286+900','1186')]),
authored('estimate-product-rounding-precision','Compare product estimates made at different rounding places',
 'For 4,328 × 6, which estimate is closer:\nrounding 4,328 to the nearest thousand or nearest hundred?', 'Nearest hundred: 25,800 is closer than 24,000',
 'For four thousand three hundred twenty-eight times six, which estimate is closer: rounding the first factor to the nearest thousand or nearest hundred?',[
 ('NEAREST THOUSAND','Round the first factor to four thousand','4,328 → 4,000\n4,000 × 6 = 24,000',
 'To the nearest thousand, four thousand three hundred twenty-eight rounds to four thousand. The estimated product is twenty-four thousand.'),
 ('NEAREST HUNDRED','Keep more place-value detail','4,328 → 4,300\n4,300 × 6 = 25,800',
 'To the nearest hundred, it rounds to four thousand three hundred. The estimated product is twenty-five thousand eight hundred.'),
 ('EXACT CHECK','Compute the original product to compare distances','4,328 × 6 = 25,968',
 'The exact product is twenty-five thousand nine hundred sixty-eight.'),
 ('COMPARE ERRORS','A smaller distance means a closer estimate','25,968 − 24,000 = 1,968\n25,968 − 25,800 = 168',
 'The estimates are one thousand nine hundred sixty-eight away and one hundred sixty-eight away. Nearest hundred gives the closer estimate here.')],
 g(4,3,'4Rev',5),equalities=[('4000*6','24000'),('4300*6','25800'),('4328*6','25968'),('25968-24000','1968'),('25968-25800','168')]),
authored('estimate-closest-product-choice','Compare supplied product estimates by their errors',
 'Which is closest to 73 × 418?\nA: 70 × 400; B: 70 × 420; C: 80 × 400', 'B: 29,400, with error 1,114',
 'Which estimate is closest to seventy-three times four hundred eighteen? Compare seventy times four hundred, seventy times four hundred twenty, and eighty times four hundred.',[
 ('EVALUATE THE OPTIONS','Work out each proposed product','A: 28,000; B: 29,400; C: 32,000',
 'The proposed products are twenty-eight thousand, twenty-nine thousand four hundred, and thirty-two thousand.'),
 ('CHECK THE ORIGINAL','Split the second factor for the exact calculation','73 × 418 = 73 × 400 + 73 × 18\n= 29,200 + 1,314 = 30,514',
 'For an accuracy check, the exact product is thirty thousand five hundred fourteen.'),
 ('COMPARE DISTANCES','Subtract the smaller number from the larger','A: 2,514 away; B: 1,114 away\nC: 1,486 away',
 'Compare each estimate with the exact product. Their distances are two thousand five hundred fourteen, one thousand one hundred fourteen, and one thousand four hundred eighty-six.'),
 ('SELECT THE CLOSEST','The smallest error belongs to B','B: 70 × 420 = 29,400',
 'B has the smallest error. Nearby rounded factors often help, but comparing the resulting products confirms which supplied estimate is closest.')],
 g(5,5,1,9),equalities=[('70*400','28000'),('70*420','29400'),('80*400','32000'),('73*418','30514'),('30514-28000','2514'),('30514-29400','1114'),('32000-30514','1486')]),
authored('estimate-reasonable-quotient','Check quotient estimates with multiplication',
 'Which estimate is most reasonable?\nA: 2,786 ÷ 7 ≈ 400; B: 854 ÷ 8 ≈ 200\nC: 1,608 ÷ 4 ≈ 40', 'A: about 400',
 'Which quotient estimate is most reasonable? Two thousand seven hundred eighty-six divided by seven is about four hundred; eight hundred fifty-four divided by eight is about two hundred; or one thousand six hundred eight divided by four is about forty?',[
 ('CHECK A','Multiply the estimate by its divisor','400 × 7 = 2,800\n2,800 is close to 2,786',
 'For A, four hundred times seven is two thousand eight hundred, very close to the dividend.'),
 ('CHECK B','The product should be close to the original dividend','200 × 8 = 1,600\n1,600 is far from 854',
 'For B, two hundred times eight is one thousand six hundred. That is far from eight hundred fifty-four.'),
 ('CHECK C','Watch for a missing zero in the estimate','40 × 4 = 160\n160 is far from 1,608',
 'For C, forty times four is one hundred sixty, far too small.'),
 ('CHOOSE THE REASONABLE ONE','Use an easy nearby multiple','2,786 ÷ 7 ≈ 2,800 ÷ 7 = 400',
 'Choose A. Replacing the dividend with a nearby easy multiple gives a reasonable estimate, and multiplication checks its size.')],
 g(4,5,3,10),equalities=[('400*7','2800'),('200*8','1600'),('40*4','160'),('2800/7','400')]),
authored('estimate-round-whole-dividend','Estimate a quotient by rounding the dividend',
 'Estimate 318 ÷ 6 by rounding 318\nto the nearest hundred.', '50',
 'Estimate three hundred eighteen divided by six by rounding three hundred eighteen to the nearest hundred.',[
 ('IDENTIFY WHAT CHANGES','The instruction names the dividend','Round 318; keep the divisor 6',
 'The dividend is three hundred eighteen. Round it, and leave the divisor six unchanged.'),
 ('ROUND','Inspect the tens digit for nearest hundred','318 → 300',
 'The tens digit is one, which is less than five. Round down to three hundred.'),
 ('DIVIDE','Use the rounded dividend','318 ÷ 6 ≈ 300 ÷ 6 = 50',
 'Three hundred divided by six is fifty, so the estimated quotient is fifty.'),
 ('CHECK','Multiply by the divisor','50 × 6 = 300\n300 is close to 318',
 'Fifty times six gives the rounded dividend three hundred. It is close to the original dividend, which supports the estimate.')],
 g(4,5,'3Rev',5),equalities=[('300/6','50'),('50*6','300')]),
]
def lessons(doc):return make_lessons(SPECS,doc)
SPECS.extend([
authored('estimate-fractions-against-one','Compare a fraction sum or difference with one whole',
 'Are these less than, equal to, or greater than 1?\n4/7 + 3/7; 6/7 + 5/7; 8/9 − 5/9', 'Equal to 1; greater than 1; less than 1',
 'Compare three results with one whole: four sevenths plus three sevenths, six sevenths plus five sevenths, and eight ninths minus five ninths.',[
 ('USE ONE WHOLE','A whole has as many equal parts as the denominator','1 = 7/7 = 9/9',
 'A denominator tells how many equal parts make one whole. Seven sevenths and nine ninths each equal one.'),
 ('FIRST SUM','Add numerators when the denominators match','4/7 + 3/7 = 7/7 = 1',
 'Four sevenths plus three sevenths makes seven sevenths. This result is exactly one, so about one is also a suitable estimate.'),
 ('SECOND SUM','More than seven sevenths is more than a whole','6/7 + 5/7 = 11/7 > 1',
 'Six sevenths plus five sevenths makes eleven sevenths. Eleven parts is more than the seven parts needed for a whole.'),
 ('DIFFERENCE','Fewer than nine ninths is less than a whole','8/9 − 5/9 = 3/9 < 1',
 'Eight ninths minus five ninths leaves three ninths, less than one whole. With equal denominators, compare the resulting numerator with the denominator.')],
 g(5,4,1,1),equalities=[('4/7+3/7','1'),('6/7+5/7','11/7'),('8/9-5/9','3/9')]),
authored('estimate-compare-fraction-sums','Compare fraction sums using one-half as a benchmark',
 'Which sum is larger?\nA: 5/8 + 3/4; B: 1/5 + 2/5', 'A is larger',
 'Which sum is larger: five eighths plus three quarters, or one fifth plus two fifths? Use one half as a benchmark.',[
 ('COMPARE A WITH HALVES','Both terms in A are greater than one-half','5/8 > 4/8 = 1/2\n3/4 > 2/4 = 1/2',
 'Five eighths is more than four eighths, or one half. Three quarters is also more than one half.'),
 ('BOUND A','Two amounts greater than one-half add to more than one','A > 1/2 + 1/2 = 1',
 'Because both terms exceed one half, A is greater than one whole.'),
 ('BOUND B','Both terms in B are less than one-half','1/5 < 1/2; 2/5 < 1/2\nB < 1',
 'One fifth and two fifths are each less than one half. Their sum is less than one whole.'),
 ('COMPARE','The sums lie on opposite sides of one','A > 1 > B\nA is larger',
 'A is above one and B is below one, so A is larger. Benchmarks can settle the comparison without calculating both exact sums.')],
 g(5,4,1,10),equalities=[('4/8','1/2'),('2/4','1/2'),('1/2+1/2','1')]),
authored('estimate-large-factor-product','Round differently sized factors and keep the place value',
 'Estimate 38 × 6,032. Round 38 to tens\nand 6,032 to thousands.', '240,000',
 'Estimate thirty-eight times six thousand thirty-two. Round thirty-eight to the nearest ten and six thousand thirty-two to the nearest thousand.',[
 ('ROUND THE SMALLER FACTOR','Inspect the ones digit','38 → 40',
 'Thirty-eight rounds up to forty because the ones digit is eight.'),
 ('ROUND THE LARGER FACTOR','Inspect the hundreds digit','6,032 → 6,000',
 'Six thousand thirty-two rounds to six thousand because its hundreds digit is zero.'),
 ('MULTIPLY THE VALUES','Keep the factors of ten and one thousand','40 × 6,000 = (4 × 10) × (6 × 1,000)\n= 24 × 10,000',
 'Multiply four by six to get twenty-four. The place-value factors ten and one thousand combine to make ten thousand.'),
 ('WRITE THE ESTIMATE','Twenty-four groups of ten thousand','38 × 6,032 ≈ 240,000',
 'Twenty-four times ten thousand is two hundred forty thousand. Keep track of place value so the estimated product has the correct size.')],
 g(5,5,1,6),equalities=[('40*6000','24*10000'),('24*10000','240000')]),
authored('estimate-quotient-too-high-low','Tell whether a quotient estimate is too high or too low',
 'A friend estimates 938 ÷ 7 as 130.\nIs 130 too small, too large, or exactly correct?', 'Too small; the exact quotient is 134',
 'A friend estimates nine hundred thirty-eight divided by seven as one hundred thirty. Is the estimate too small, too large, or exactly correct?',[
 ('MULTIPLY BACK','Use the proposed quotient and the positive divisor','130 × 7 = 910',
 'Multiply the proposed quotient by seven. One hundred thirty times seven is nine hundred ten.'),
 ('COMPARE WITH THE DIVIDEND','The product falls short of the original amount','910 < 938',
 'Nine hundred ten is less than the original dividend, nine hundred thirty-eight.'),
 ('DECIDE THE DIRECTION','A larger quotient is needed to reach the dividend','130 is too small',
 'Because seven is positive, we need a larger quotient to reach the dividend. The estimate is too small.'),
 ('EXACT CHECK','The remaining twenty-eight adds four groups','938 − 910 = 28; 28 ÷ 7 = 4\n938 ÷ 7 = 130 + 4 = 134',
 'The shortfall is twenty-eight, which is four more groups of seven. The exact quotient is one hundred thirty-four, confirming the estimate was low.')],
 g(5,5,'5HW',1),equalities=[('130*7','910'),('938-910','28'),('28/7','4'),('938/7','134')]),
authored('estimate-decimal-product-options','Make a product easier by rounding one or both factors',
 'Estimate 8.4 × 29 by rounding 8.4 to a whole number.\nThen also round 29 to the nearest ten and compare.', '232 when rounding one factor; 240 when rounding both',
 'Estimate eight point four times twenty-nine by rounding eight point four to a whole number. Then also round twenty-nine to the nearest ten and compare the estimates.',[
 ('ROUND THE DECIMAL','The tenths digit four means round down','8.4 → 8',
 'Eight point four rounds to eight because its tenths digit is four.'),
 ('KEEP THE OTHER FACTOR','Use twenty-nine unchanged for the first method','8.4 × 29 ≈ 8 × 29 = 232',
 'Keeping twenty-nine unchanged gives eight times twenty-nine, or two hundred thirty-two.'),
 ('ROUND BOTH','Use the nearby ten for an easier product','29 → 30\n8.4 × 29 ≈ 8 × 30 = 240',
 'If we also round twenty-nine to thirty, the estimate becomes eight times thirty, or two hundred forty.'),
 ('FOLLOW THE REQUEST','Different stated methods can give different estimates','One rounded factor: 232\nBoth rounded factors: 240',
 'Both are estimates, made by different methods. Follow any specified rounding instruction. When the method is open, state which nearby values you used.')],
 g(5,8,'1HW',2),equalities=[('8*29','232'),('8*30','240')]),
])
